import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Mesh, PlaneGeometry, Group } = ctx.THREE;

  const group = new Group();
  group.position.fromArray(config.scenePosition || [0, 3, 0]);
  group.rotation.order = 'YXZ';
  if (config.sceneRotation) {
    group.rotation.fromArray(config.sceneRotation);
  }
  if (config.sceneScale) {
    group.scale.fromArray(config.sceneScale);
  }

  // Plane geometry: hero headline aspect ratio
  // Text content: "A machined-metal watch atelier landing with catalog, pricing, jo"
  // 31px body text, so we size the plane to accommodate readable text
  const planeGeo = new PlaneGeometry(7, 1.2);

  // Load the feature card image as the base texture
  const texturePromise = config.imageUrl
    ? ctx.textureLoader.loadTexture(config.imageUrl)
    : Promise.resolve(null);

  texturePromise.then((baseTexture) => {
    // Material: basic node material for static composition
    const mat = new MeshBasicNodeMaterial();

    if (baseTexture) {
      baseTexture.colorSpace = 'srgb';
      const baseTex = texture(baseTexture);
      mat.colorNode = baseTex;
    } else {
      // Fallback: engineered gradient surface (vertical gradient ink -> paper)
      const uvNode = uv();
      const gradientNode = mix(
        vec3(0.086, 0.086, 0.106), // #16161d ink
        vec3(0.91, 0.925, 0.949),   // #e8ecf2 paper
        uvNode.y
      );
      mat.colorNode = gradientNode;
    }

    mat.side = ctx.THREE.FrontSide;
    mat.transparent = false;

    const planeMesh = new Mesh(planeGeo, mat);
    planeMesh.receiveShadow = false;
    planeMesh.castShadow = false;
    group.add(planeMesh);

    // Store material for cleanup
    planeMesh.userData.material = mat;
    planeMesh.userData.geometry = planeGeo;
    if (baseTexture) {
      planeMesh.userData.texture = baseTexture;
    }
  });

  // Render text content from config
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let textMeshY = 0;

  for (const item of items) {
    if (!item.text) continue;

    // Body text: 31px = ~0.13 scene units (type scale body)
    const fontSize = item.typography?.fontSize || 31;
    const scaleUnit = fontSize / 240; // approximate conversion to scene units
    const color = item.role === 'body' ? '#16161d' : '#e8ecf2'; // ink for body

    const textMesh = ctx.fontAtlas.createText(item.text, {
      fontSize: fontSize,
      color: color,
      align: 'center',
      maxWidthPx: 700,
      letterSpacingPx: 0
    });

    textMesh.position.y = textMeshY;
    textMesh.position.z = 0.01; // Slight z offset to appear above plane
    group.add(textMesh);

    textMeshY -= scaleUnit * 0.5; // Stack text items vertically

    // Store for cleanup
    if (!group.userData.textMeshes) {
      group.userData.textMeshes = [];
    }
    group.userData.textMeshes.push(textMesh);
  }

  // Cleanup function
  group.userData.cleanup = function () {
    // Dispose geometries and materials
    group.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (child.material.map) child.material.map.dispose();
          child.material.dispose();
        }
        if (child.userData.texture) child.userData.texture.dispose();
      }
    });

    // Clear text meshes
    if (group.userData.textMeshes) {
      group.userData.textMeshes.forEach((tm) => {
        if (tm.geometry) tm.geometry.dispose();
        if (tm.material) tm.material.dispose();
      });
      group.userData.textMeshes.length = 0;
    }
  };

  // Event handlers object (empty for static node)
  group.userData.handlers = {};

  return group;
}
